            if (!selectedStart)
                throw new Error("Pick a start first.");
            if (!selectedEnd)
                throw new Error("Pick how long first.");
            renting = true;
            error = null;
            emit();
            try {
                const result = await rentResource(rental, selectedStart, selectedEnd, values, timeZone ?? undefined);
                if (result.kind === "redirect") {
                    window.location.href = result.url;
                }
                else {
                    confirmed = result;
                }
