        .filter((f) => !f.deleted && f.type && FIELD_TYPES.includes(f.type))
        .map((f) => ({
        target: f.target ?? "",
        label: f.label ?? f.target ?? "",
        type: f.type,
        ...(Array.isArray(f.options) && f.options.length ? { options: f.options } : {}),
