/** The rest of the Create Booking request: the form values as the formSubmission, and Wix's own notifications. */
export function bookingOptions(formValues) {
    return {
        participantNotification: { notifyParticipants: true, metadata: { channels: "EMAIL,SMS" } },
        sendSmsReminder: true,
        formSubmission: formValues,
    };
}
export const bookingIdOf = (res) => rawId(res?.booking);
export const contactOf = (res) => res?.booking?.contactDetails ?? undefined;
/** The Create Cart body holding the booking: catalogItemId is the BOOKING id and appId the RENTALS app. */
export function cartRequest(bookingIds, contact, locationId) {
    const cart = { source: { channelType: "WEB" } };
    if (locationId)
        cart.businessInfo = { locationId };
    if (contact) {
        cart.customerInfo = {
            ...(contact.firstName ? { firstName: contact.firstName } : {}),
            ...(contact.lastName ? { lastName: contact.lastName } : {}),
            ...(contact.phone ? { phone: contact.phone } : {}),
            ...(contact.email ? { email: contact.email } : {}),
        };
    }
    return { catalogItems: bookingIds.map((id) => ({ quantity: 1, catalogReference: { catalogItemId: id, appId: RENTALS_APP_ID } })), cart };
}
export const cartIdOf = (res) => rawId(res) || rawId(res?.cart);
export const cartTotal = (calc) => Number(calc?.summary?.priceSummary?.total?.amount ?? 0);
/** Hosted checkout whenever a card is involved: a cancellation fee, or a non-zero total not paid fully offline. */
export function checkoutRequired(rental, calc) {
    if (rental.cancellationFeeEnabled)
        return true;
    if (cartTotal(calc) === 0)
        return false;
    return calc?.cart?.lineItems?.[0]?.paymentConfig?.paymentOption !== "FULL_PAYMENT_OFFLINE";
}
export function checkoutRedirectRequest(cartId, origin) {
    return { ecomCheckout: { checkoutId: cartId }, callbacks: origin ? { postFlowUrl: `${origin}/` } : {} };
}
export function confirmedResult(bookingId, order) {
    return { kind: "confirmed", bookingId, orderId: order?.orderId ?? (rawId(order?.order) || null) };
}
/** Wix's refusal codes a visitor sees, in plain words. */
export function friendlyError(message) {
    if (/SLOT_NOT_AVAILABLE/.test(message))
        return "That time was just taken. Pick another start.";
    if (/INVALID_DURATION/.test(message))
        return "That length is outside what this rental allows. Pick another length.";
    if (/PREMIUM_VALIDATION_FAILED|SITE_NOT_ACCEPTING/.test(message))
        return "This site cannot take online bookings yet (no payment method or plan). Contact the business directly.";
    if (/END_OPTIONS_NOT_SUPPORTED/.test(message))
        return "This rental is booked by the day.";
    return message;
}

