// The rentals listing as a framework-free store — the logic behind useRentals, usable from React
// (useRentals wraps it with useSyncExternalStore), from a static page or Vue/Svelte (subscribe and
// render), or as the specification for a port. Pages are 20 long with `hasMore`/`loadMore()`.
// SSR-friendly: seed with `initialRentals` (+ `initialHasMore`) and nothing is fetched for the first
// paint; without them `start()` loads the first page. One store per mounted listing.
import { RENTALS_PAGE_SIZE, fetchRentals } from "./rentals.js";
export function createRentalsStore({ initialRentals, initialHasMore = false, pageSize = RENTALS_PAGE_SIZE } = {}) {
    let rentals = initialRentals ?? null;
    let hasMore = initialHasMore;
    let loadingMore = false;
    let error = null;
    let started = false;
    let generation = 0;
    const listeners = new Set();
    let snapshot = null;
    const emit = () => {
        snapshot = null;
        for (const fn of listeners)
            fn();
    };
    function getState() {
        if (snapshot)
            return snapshot;
        snapshot = { rentals, hasMore, loadingMore, error };
        return snapshot;
    }
    function loadFirstPage() {
        const id = ++generation;
        rentals = null;
        hasMore = false;
        error = null;
        emit();
        fetchRentals({ limit: pageSize, offset: 0 })
            .then((page) => {
            if (!started || generation !== id)
                return; // superseded — drop it
            rentals = page.items;
            hasMore = page.hasMore;
            emit();
        })
            .catch((e) => {
            if (!started || generation !== id)
                return;
            rentals = [];
            error = e instanceof Error ? e.message : String(e);
            emit();
        });
    }
    return {
        getState,
        subscribe(fn) {
            listeners.add(fn);
            return () => listeners.delete(fn);
        },
        start() {
            if (started)
                return;
            started = true;
            if (!initialRentals)
                loadFirstPage();
        },
        stop() {
            started = false;
            generation++;
        },
        async loadMore() {
            if (!started || loadingMore || !hasMore || !rentals)
                return;
            const id = generation;
            loadingMore = true;
            emit();
            try {
                const page = await fetchRentals({ limit: pageSize, offset: rentals.length });
                if (!started || generation !== id)
                    return;
                rentals = [...rentals, ...page.items];
                hasMore = page.hasMore;
            }
            catch (e) {
                if (!started || generation !== id)
                    return;
                error = e instanceof Error ? e.message : String(e);
            }
            finally {
                if (generation === id)
                    loadingMore = false;
                emit();
            }
        },
    };
}

